authenticate=async function(event,register){event.preventDefault();const email=document.querySelector('#email').value.trim(),password=document.querySelector('#password').value,button=document.querySelector('#authsubmit95'),error=document.querySelector('#autherror');if(register&&password!==document.querySelector('#confirm').value){error.textContent='Le password non coincidono.';return}button.disabled=true;O.pendingEmail=email;authDraft95.email=email;try{if(register){await remote('POST','/v1/auth/register',{email,password,name:document.querySelector('#authname').value.trim(),birth_date:document.querySelector('#birth_date').value,adult_confirmed:document.querySelector('#adult').checked});O.verifyPassword=password;verifyOnline('Ti abbiamo inviato un codice. Controlla anche lo spam.')}else{await remote('POST','/v1/auth/login',{email,password});await enterOnline()}}catch(e){error.textContent=e.message;if(e.status===403&&e.code!=='account_suspended'){O.verifyPassword=password;verifyOnline(e.message)}}finally{button.disabled=false}};
